#!/usr/bin/env python3
from itertools import combinations
from fractions import Fraction

def graph(alpha,beta):
    # Vertex (i,j) represents ideal (p^i q^j), excluding R=(0,0) and 0=(alpha,beta).
    V=[(i,j) for i in range(alpha+1) for j in range(beta+1)
       if (i,j)!=(0,0) and (i,j)!=(alpha,beta)]
    N=[set() for _ in V]
    for x,(i,j) in enumerate(V):
        for y in range(x+1,len(V)):
            k,l=V[y]
            # Intersection is generated by lcm, nonzero iff not both exponents hit the maxima.
            if max(i,k)<alpha or max(j,l)<beta:
                N[x].add(y); N[y].add(x)
    return V,N

def classes(alpha,beta,V):
    A=[];B=[];C=[]
    for idx,(i,j) in enumerate(V):
        if i==alpha:
            A.append(idx)
        elif j==beta:
            B.append(idx)
        else:
            C.append(idx)
    return A,B,C

def zero_forces(S,N):
    blue=set(S)
    while True:
        move=None
        for v in sorted(blue):
            W=N[v]-blue
            if len(W)==1:
                move=next(iter(W))
                break
        if move is None:
            return len(blue)==len(N)
        blue.add(move)

def polynomial(N):
    n=len(N); d={}
    for k in range(n+1):
        c=0
        for S in combinations(range(n),k):
            if zero_forces(S,N):
                c+=1
        if c:d[k]=c
    return d

def predicted(alpha,beta):
    N=alpha*beta+alpha+beta-1
    if alpha==beta==1:
        return {2:1}
    c=alpha*beta-1
    E=alpha*beta+(alpha+beta)*c
    return {N-2:E,N-1:N,N:1}

def rank_fraction(M):
    A=[[Fraction(x) for x in row] for row in M]
    m=len(A); n=len(A[0]) if A else 0
    r=0;c=0
    while r<m and c<n:
        p=next((i for i in range(r,m) if A[i][c]),None)
        if p is None:
            c+=1; continue
        A[r],A[p]=A[p],A[r]
        z=A[r][c]
        A[r]=[x/z for x in A[r]]
        for i in range(m):
            if i!=r and A[i][c]:
                z=A[i][c]
                A[i]=[A[i][j]-z*A[r][j] for j in range(n)]
        r+=1;c+=1
    return r

def rank_witness(alpha,beta,V,N):
    if alpha==beta==1:
        A=[[0]*len(V) for _ in V]
        assert rank_fraction(A)==0
        return 0
    Acl,Bcl,Ccl=classes(alpha,beta,V)
    kind={}
    for i in Acl: kind[i]=0
    for i in Bcl: kind[i]=1
    for i in Ccl: kind[i]=2
    vec=[(1,0),(0,1),(1,1)]
    M=[[vec[kind[i]][0]*vec[kind[j]][0]+vec[kind[i]][1]*vec[kind[j]][1]
        for j in range(len(V))] for i in range(len(V))]
    for i in range(len(V)):
        for j in range(i+1,len(V)):
            assert ((M[i][j]!=0)==(j in N[i]))
    assert rank_fraction(M)==2
    return 2

def degree_multiset(N):
    return sorted(len(x) for x in N)

# Exact graph/polynomial checks on every small exponent pair.
for alpha in range(1,5):
    for beta in range(alpha,5):
        V,N=graph(alpha,beta)
        A,B,C=classes(alpha,beta,V)
        assert len(A)==beta
        assert len(B)==alpha
        assert len(C)==alpha*beta-1
        # Only A-B pairs are nonedges, except the omitted diagonal.
        for i in range(len(V)):
            for j in range(i+1,len(V)):
                expected=not ((i in A and j in B) or (i in B and j in A))
                assert ((j in N[i])==expected)
        r=rank_witness(alpha,beta,V,N)
        if len(V)<=15:
            brute=polynomial(N)
            assert brute==predicted(alpha,beta),(alpha,beta,brute,predicted(alpha,beta))
            print(f"({alpha},{beta}): N={len(V)}, polynomial={brute}, witness_rank={r}")
        else:
            print(f"({alpha},{beta}): N={len(V)}, predicted={predicted(alpha,beta)}, witness_rank={r}")

# Verify the two nontrivial polynomial collisions and graph nonisomorphism via degree multisets.
for (a,b),(c,d) in [((1,9),(3,4)),((1,11),(2,7))]:
    assert predicted(a,b)==predicted(c,d)
    Va,Na=graph(a,b); Vc,Nc=graph(c,d)
    assert degree_multiset(Na)!=degree_multiset(Nc)
    print(f"collision ({a},{b}) ~ ({c},{d}): polynomial={predicted(a,b)}, degree_multisets_differ")

# Exhaustively corroborate the collision classification in a large finite box.
seen={}
collisions=set()
for a in range(1,80):
    for b in range(a,80):
        key=tuple(sorted(predicted(a,b).items()))
        if key in seen and seen[key]!=(a,b):
            collisions.add(tuple(sorted((seen[key],(a,b)))))
        else:
            seen[key]=(a,b)
assert collisions=={
    tuple(sorted(((1,9),(3,4)))),
    tuple(sorted(((1,11),(2,7))))
}
print("COLLISION_CENSUS_OK")
print("VERIFY_OK")
